from ortools.sat.python import cp_model
import itertools
import json

def main():
    intersections = set(range(10))
    edges = {(5,8), (8,6), (6,2), (2,7), (7,3), (3,4), (4,0), (0,9), (9,1), 
             (1,2), (2,8), (8,9), (9,7), (7,6), (6,1), (1,5)}

    undirected_edges = set()
    for (i, j) in edges:
        undirected_edges.add((i, j))
        undirected_edges.add((j, i))

    length = {
        (5,8): 3.16, (8,5): 3.16,
        (8,6): 8.06, (6,8): 8.06,
        (6,2): 4.12, (2,6): 4.12,
        (2,7): 6.00, (7,2): 6.00,
        (7,3): 7.28, (3,7): 7.28,
        (3,4): 5.83, (4,3): 5.83,
        (4,0): 9.49, (0,4): 9.49,
        (0,9): 10.77, (9,0): 10.77,
        (9,1): 4.47, (1,9): 4.47,
        (1,2): 5.39, (2,1): 5.39,
        (2,8): 10.00, (8,2): 10.00,
        (8,9): 12.21, (9,8): 12.21,
        (9,7): 6.40, (7,9): 6.40,
        (7,6): 2.24, (6,7): 2.24,
        (6,1): 1.41, (1,6): 1.41,
        (1,5): 5.39, (5,1): 5.39
    }

    collection_time = {
        (5,8): 8.0, (8,5): 8.0,
        (8,6): 12.0, (6,8): 12.0,
        (6,2): 6.0, (2,6): 6.0,
        (2,7): 9.0, (7,2): 9.0,
        (7,3): 11.0, (3,7): 11.0,
        (3,4): 8.0, (4,3): 8.0,
        (4,0): 14.0, (0,4): 14.0,
        (0,9): 16.0, (9,0): 16.0,
        (9,1): 7.0, (1,9): 7.0,
        (1,2): 8.0, (2,1): 8.0,
        (2,8): 15.0, (8,2): 15.0,
        (8,9): 18.0, (9,8): 18.0,
        (9,7): 10.0, (7,9): 10.0,
        (7,6): 4.0, (6,7): 4.0,
        (6,1): 3.0, (1,6): 3.0,
        (1,5): 8.0, (5,1): 8.0
    }

    depot = 0

    model = cp_model.CpModel()

    x = {}
    for (i, j) in undirected_edges:
        min_val = 1 if (i, j) in edges or (j, i) in edges else 0
        x[(i, j)] = model.NewIntVar(min_val, 10, f"x_{i}_{j}")

    for (i, j) in edges:
        total_traversal = model.NewIntVar(1, 20, f"total_{i}_{j}")
        model.Add(total_traversal == x[(i, j)] + x[(j, i)])
        model.Add(total_traversal >= 1)

    for v in intersections:
        incident_edges = [(v, j) for (i, j) in undirected_edges if i == v]
        if incident_edges:
            degree_sum = sum(x[edge] for edge in incident_edges)
            half_degree = model.NewIntVar(0, 10, f"half_degree_{v}")
            model.Add(degree_sum == 2 * half_degree)

    n = len(intersections)
    all_vertices = list(intersections)

    for v in intersections:
        S = {v}
        cut_edges = []
        for (i, j) in undirected_edges:
            if (i in S and j not in S) or (j in S and i not in S):
                cut_edges.append(x[(i, j)])
        if cut_edges:
            model.Add(sum(cut_edges) >= 1)

    for v1 in intersections:
        for v2 in intersections:
            if v1 < v2:
                S = {v1, v2}
                cut_edges = []
                for (i, j) in undirected_edges:
                    if (i in S and j not in S) or (j in S and i not in S):
                        cut_edges.append(x[(i, j)])
                if cut_edges:
                    model.Add(sum(cut_edges) >= 1)

    for v in intersections:
        S = set(intersections) - {v}
        cut_edges = []
        for (i, j) in undirected_edges:
            if (i in S and j not in S) or (j in S and i not in S):
                cut_edges.append(x[(i, j)])
        if cut_edges:
            model.Add(sum(cut_edges) >= 1)

    objective_terms = []

    for (i, j) in edges:
        total_traversal = model.NewIntVar(1, 20, f"obj_total_{i}_{j}")
        model.Add(total_traversal == x[(i, j)] + x[(j, i)])

        scaled_length = int(round(length[(i, j)] * 100))
        scaled_collection = int(round(collection_time[(i, j)] * 100))

        length_term = model.NewIntVar(0, 100000, f"length_term_{i}_{j}")
        model.Add(length_term == total_traversal * scaled_length)

        objective_terms.append(length_term)

    total_length_terms = sum(objective_terms)

    total_constant = 0
    for (i, j) in edges:
        total_constant += int(round(-length[(i, j)] * 100 + collection_time[(i, j)] * 100))

    model.Minimize(total_length_terms + total_constant)

    solver = cp_model.CpSolver()
    solver.parameters.max_time_in_seconds = 30.0
    solver.parameters.num_search_workers = 8

    status = solver.Solve(model)

    if status in (cp_model.OPTIMAL, cp_model.FEASIBLE):
        total_cost = 0
        edge_traversals = {}

        for (i, j) in edges:
            total_traversal = solver.Value(x[(i, j)]) + solver.Value(x[(j, i)])
            edge_traversals[(i, j)] = total_traversal
            cost = length[(i, j)] * (total_traversal - 1) + collection_time[(i, j)]
            total_cost += cost

        from collections import defaultdict

        adj = defaultdict(list)
        for (i, j) in undirected_edges:
            count = solver.Value(x[(i, j)])
            for _ in range(count):
                adj[i].append(j)

        def hierholzer(start):
            circuit = []
            stack = [start]

            while stack:
                v = stack[-1]
                if adj[v]:
                    u = adj[v].pop()
                    adj[u].remove(v)
                    stack.append(u)
                else:
                    circuit.append(stack.pop())

            return circuit[::-1]

        route = hierholzer(depot)

        print(json.dumps({
            "route": route,
            "total_cost": round(total_cost, 2)
        }))

    else:
        print(json.dumps({
            "route": [],
            "total_cost": 0.0
        }))

if __name__ == "__main__":
    main()
